window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ae9ce7ab8ff64b3b"]={"versions": [{"id": "FIG-ae9ce7ab8ff64b3b", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (AUTOSAR-Metamodell / Definitionsebene).</li>\n<li><strong>Technischer Zweck & funktionale Einordnung:</strong></li>\n<li>Definiert die Top-Level-Metamodell-Struktur für die <strong>ECU-Konfigurations-Parameterdefinition</strong> (BSW-Modul-Deskriptoren).</li>\n<li>Bildet die formale Schablone (Schema / Template), anhand derer konkrete BSW-Module (z. B. Can, Com, Os, Dem) und deren Konfigurationsparameter definiert werden, bevor diese in der ECU-Konfigurations-Wertemenge (<code>EcucValueCollection</code> bzw. Modulkonfigurationen) instanziiert werden.</li>\n<li>Verankert die Konfigurationsdefinitionen in der globalen AUTOSAR-ARXML-Hierarchie als vollwertige Paket-Elemente (<code>ARElement</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Entitäten & Klassenhierarchie</p>\n<ul class=\"fig-list\">\n<li><strong><code>ARObject</code>:</strong></li>\n<li>Wurzelklasse des gesamten AUTOSAR-Metamodells.</li>\n<li><strong><code>Identifiable</code></strong> (Stereotyp <code>«atpIdentifiable»</code>):</li>\n<li>Spezialisierung von <code>ARObject</code>.</li>\n<li>Basis für alle adressierbaren Metamodell-Elemente im ARXML-Baum.</li>\n<li><strong>Attribute:</strong></li>\n<li><code>shortName: Identifier</code> (eindeutiger Name innerhalb des Namensraums/Pfads).</li>\n<li><code>category: String [0..1]</code> (semantische Subklassifikation).</li>\n<li><code>uuid: String</code> (global eindeutige Identifikations-GUID).</li>\n<li><strong><code>ARElement</code></strong> (Stereotyp <code>«atpIdentifiable»</code>, Eigenschaft <code>NonSplitableElement</code>):</li>\n<li>Spezialisierung von <code>Identifiable</code>.</li>\n<li>Repräsentiert ein eigenständiges Top-Level-Element eines <code>AR-PACKAGE</code>.</li>\n<li><code>NonSplitableElement</code>: Darf im Gegensatz zu splitbaren Elementen nicht über mehrere physische ARXML-Dateien aufgeteilt fragmentiert werden; die Definition muss atomar deklariert sein.</li>\n<li><strong><code>EcuParameterDefinition</code>:</strong></li>\n<li>Spezialisierung von <code>ARElement</code>.</li>\n<li>Wurzelelement/Container der Parameterspezifikation für eine Steuergerätekonfiguration.</li>\n<li><strong><code>ModuleDef</code></strong> (mit Mixin/Aspekt <code>ParamConfMultiplicity</code>):</li>\n<li>Spezialisierung von <code>ARElement</code>. Repräsentiert die Konfigurationsdefinition eines konkreten BSW-Moduls (z. B. <code>Can</code>, <code>Fee</code>).</li>\n<li><strong>Attribut:</strong> <code>implementationConfigVariant: String [0..1]</code> (definiert die zulässigen/unterstützten Konfigurationsvarianten wie <em>PreCompile</em>, <em>LinkTime</em>, <em>PostBuild</em>).</li>\n<li><strong><code>ContainerDef</code></strong> (mit Mixin/Aspekt <code>ParamConfMultiplicity</code>):</li>\n<li>Spezialisierung von <code>Identifiable</code> (ist <strong>kein</strong> <code>ARElement</code>, kann folglich nicht direkt in <code>AR-PACKAGE</code> liegen, sondern nur innerhalb eines Moduls bzw. Eltern-Containers).</li>\n<li>Struktur- und Gruppierungselement für Parameter und Unter-Container.</li>\n<li><strong>Attribut:</strong> <code>postBuildChangeable: Boolean</code> (normatives Flag, ob die Parameterwerte dieses Containers zur Laufzeit bzw. nach dem Kompilieren/Flushen als Post-Build-Loadable/Selectable austauschbar sein dürfen).</li>\n</ul>\n<p class=\"fig-p\">#### Assoziationen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li>*<em><code>EcuParameterDefinition</code> $\\rightarrow$ <code>ModuleDef</code> (<code>+module</code>, Kardinalität <code>1..</em></code>):**</li>\n<li>Eine <code>EcuParameterDefinition</code> bündelt mindestens eine oder beliebig viele BSW-Moduldefinitionen.</li>\n<li>*<em><code>ModuleDef</code> $\\blacktriangleright$ <code>ContainerDef</code> (<code>+container</code>, Kardinalität <code>1..</em></code>):**</li>\n<li>Strenge Komposition: Ein BSW-Modul besteht aus mindestens einem Root-<code>ContainerDef</code>. Die Lebensdauer der Container ist fest an das übergeordnete <code>ModuleDef</code> gebunden.</li>\n<li><strong><code>ModuleDef</code> $\\rightarrow$ <code>ModuleDef</code> (<code>+refinedModuleDef</code>, Kardinalität <code>0..1</code>):</strong></li>\n<li>Reflexive Assoziation zur <strong>Modul-Refinierung</strong> (<em>Module Refinement</em>): Ermöglicht es Halbleiter-/Stack-Vendors, eine standardisierte BSW-Moduldefinition (<code>ModuleDef</code>) durch herstellerspezifische Parameter und Container zu erweitern bzw. einzuschränken, ohne den AUTOSAR-Standarddeskriptor zu verändern.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Nicht zutreffend (rein statisches Metamodell):</strong></li>\n<li>Das Diagramm enthält keine Laufzeitinteraktionen, Zustände, Sequenzen oder OS-/Task-Trigger.</li>\n<li><strong>Verarbeitungskontext im AUTOSAR-Toolchain-Ablauf:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>Bereitstellung der <code>ModuleDef</code>-Standardbeschreibungen durch den BSW-Lieferanten (BSW-Paket).</li>\n<li>Optionales Ausführen der Refinement-Assoziation (<code>refinedModuleDef</code>) durch Vendor-Tools.</li>\n<li>Einlesen der <code>EcuParameterDefinition</code> in den ECU-Konfigurator (z. B. DaVinci Configurator, EB tresos).</li>\n<li>Validierung der Modul-Multiplizitäten (<code>ParamConfMultiplicity</code>) und Bindungsvarianten (<code>implementationConfigVariant</code>) gegen die konkreten Eingabewerte (<code>EcucModuleConfigurationValues</code>).</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Trennung von Metadaten und Werten:</strong></li>\n<li>Entwickler müssen strikt zwischen der Definitionsklasse (<code>ModuleDef</code>, <code>ContainerDef</code>) und der Instanziierungsebene (<code>EcucModuleConfigurationValues</code>, <code>EcucContainerValue</code>) unterscheiden. Änderungen hier betreffen Codegeneratoren und XML-Validatoren, nicht den C-Treiber direkt.</li>\n<li><strong>Vendor Module Refinement (<code>refinedModuleDef</code>):</strong></li>\n<li>Vendor-spezifische Erweiterungen (z. B. HW-spezifische Clock-Divider in <code>Mcu</code> oder erweiterte Filter in <code>Can</code>) dürfen die standardisierte <code>ModuleDef</code> nicht brechen. Das <code>refinedModuleDef</code> garantiert Rückwärtskompatibilität zum AUTOSAR-Standard bei gleichzeitiger Validierung herstellerspezifischer Konfigurationen.</li>\n<li><strong>Einfluss auf Speicherklassen & Codegenerierung (<code>postBuildChangeable</code> & <code>implementationConfigVariant</code>):</strong></li>\n<li><code>postBuildChangeable == true</code>: Container-Daten müssen im C-Code zwingend in relokierbaren Strukturen (RAM-Zeiger oder Flash-Blocks mit konstanter Basisadresse) abgelegt werden, typischerweise als Typ-Definitionen für Deskriptor-Arrays.</li>\n<li><code>postBuildChangeable == false</code> (bzw. <em>PreCompile</em>): Parameter aus diesem Container fließen als Präprozessor-Makros (<code>#define</code>) oder <code>const</code>-Strukturen direkt in den ROM/Flash-Code ein.</li>\n<li><strong>ARXML-Serialisierung (<code>NonSplitableElement</code>):</strong></li>\n<li>Bei der Tool-Entwicklung und Versionskontrolle muss beachtet werden, dass <code>ModuleDef</code> als <code>NonSplitableElement</code> stets in einem konsistenten, nicht fragmentierten XML-Knoten persistiert wird.</li>\n</ul>"}, {"id": "FIG-a6ede4f7b3ece0cd", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (AUTOSAR-Metamodell / Definitionsebene).</li>\n<li><strong>Technischer Zweck & funktionale Einordnung:</strong></li>\n<li>Definiert die Top-Level-Metamodell-Struktur für die <strong>ECU-Konfigurations-Parameterdefinition</strong> (BSW-Modul-Deskriptoren).</li>\n<li>Bildet die formale Schablone (Schema / Template), anhand derer konkrete BSW-Module (z. B. Can, Com, Os, Dem) und deren Konfigurationsparameter definiert werden, bevor diese in der ECU-Konfigurations-Wertemenge (<code>EcucValueCollection</code> bzw. Modulkonfigurationen) instanziiert werden.</li>\n<li>Verankert die Konfigurationsdefinitionen in der globalen AUTOSAR-ARXML-Hierarchie als vollwertige Paket-Elemente (<code>ARElement</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Entitäten & Klassenhierarchie</p>\n<ul class=\"fig-list\">\n<li><strong><code>ARElement</code></strong> (Eigenschaft <code>PackageableElement</code>):</li>\n<li>Repräsentiert ein eigenständiges Top-Level-Element eines Pakets (<code>AR-PACKAGE</code>).</li>\n<li>Trägt die Kennzeichnung <code>PackageableElement</code> als verpackbares Metamodellelement.</li>\n<li><strong><code>EcuParameterDefinition</code>:</strong></li>\n<li>Spezialisierung von <code>ARElement</code>.</li>\n<li>Wurzelelement der Parameterspezifikation für eine Steuergerätekonfiguration.</li>\n<li><strong><code>ModuleDef</code></strong> (mit Mixin/Aspekt <code>ParamConfMultiplicity</code>):</li>\n<li>Spezialisierung von <code>ARElement</code>. Repräsentiert die Konfigurationsdefinition eines BSW-Moduls.</li>\n<li><strong>Attribut:</strong> <code>supportedConfigVariant: ConfigurationVariant [1..<em>]</code> (definiert als Aufzählungstyp typisiert mit Kardinalität <code>1..</em></code> die vom Modul unterstützten Konfigurationsvarianten wie <em>PreCompile</em>, <em>LinkTime</em> oder <em>PostBuild</em>).</li>\n<li><strong><code>ContainerDef</code></strong> (mit Mixins/Aspekten <code>Identifiable</code>, <code>ParamConfMultiplicity</code>):</li>\n<li>Struktur- und Gruppierungselement für Parameter und Unter-Container, das die Eigenschaften von <code>Identifiable</code> und <code>ParamConfMultiplicity</code> inkorporiert.</li>\n<li><strong>Attribut:</strong> <code>postBuildChangeable: Boolean</code> (normatives Flag, ob die Parameterwerte dieses Containers nach dem Kompilieren/Bauen austauschbar sein dürfen).</li>\n</ul>\n<p class=\"fig-p\">#### Assoziationen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li>*<em><code>EcuParameterDefinition</code> $\\rightarrow$ <code>ModuleDef</code> (<code>+module</code>, Kardinalität <code>1..</em></code>):**</li>\n<li>Eine <code>EcuParameterDefinition</code> bündelt mindestens eine oder beliebig viele BSW-Moduldefinitionen.</li>\n<li>*<em><code>ModuleDef</code> $\\blacktriangleright$ <code>ContainerDef</code> (<code>+container</code>, Kardinalität <code>1..</em></code>):**</li>\n<li>Strenge Komposition: Ein BSW-Modul besteht aus mindestens einem Root-<code>ContainerDef</code>. Die Lebensdauer der Container ist fest an das übergeordnete <code>ModuleDef</code> gebunden.</li>\n<li><strong><code>ModuleDef</code> $\\rightarrow$ <code>ModuleDef</code> (<code>+refinedModuleDef</code>, Kardinalität <code>0..1</code>):</strong></li>\n<li>Reflexive Assoziation zur Modul-Refinierung (<em>Module Refinement</em>): Ermöglicht die Spezialisierung bzw. Erweiterung einer bestehenden Moduldefinition.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Nicht zutreffend (rein statisches Metamodell):</strong></li>\n<li>Das Diagramm enthält keine Laufzeitinteraktionen, Zustände, Sequenzen oder OS-/Task-Trigger.</li>\n<li><strong>Verarbeitungskontext im AUTOSAR-Toolchain-Ablauf:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>Bereitstellung der <code>ModuleDef</code>-Standardbeschreibungen durch den BSW-Lieferanten (BSW-Paket).</li>\n<li>Optionales Ausführen der Refinement-Assoziation (<code>refinedModuleDef</code>) durch Vendor-Tools.</li>\n<li>Einlesen der <code>EcuParameterDefinition</code> in den ECU-Konfigurator (z. B. DaVinci Configurator, EB tresos).</li>\n<li>Validierung der Modul-Multiplizitäten (<code>ParamConfMultiplicity</code>) und Bindungsvarianten (<code>implementationConfigVariant</code>) gegen die konkreten Eingabewerte (<code>EcucModuleConfigurationValues</code>).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Verbindlichkeit der Struktur:</strong> Jede AUTOSAR-konforme BSW-Moduldefinition muss als <code>ModuleDef</code> angelegt sein und zwingend mindestens einen Wurzelcontainer (<code>+container [1..*]</code>) deklarieren.</li>\n<li><strong>Paketierung:</strong> <code>EcuParameterDefinition</code> und <code>ModuleDef</code> sind als <code>ARElement</code> spezialisiert und tragen den Status <code>PackageableElement</code>, wodurch sie direkt in ARXML-Paketen verwaltet werden.</li>\n<li><strong>Post-Build-Restriktion:</strong> Das Attribut <code>postBuildChangeable</code> an <code>ContainerDef</code> schreibt bindend vor, ob Werte der in diesem Container enthaltenen Parameter zur Post-Build-Zeit geändert werden dürfen.</li>\n<li><strong>Konfigurationsvarianten:</strong> Durch das Attribut <code>supportedConfigVariant: ConfigurationVariant [1..*]</code> muss für jede Moduldefinition mindestens eine explizit typisierte Konfigurationsvariante verbindlich festgelegt sein.</li>\n</ul>"}, {"id": "FIG-a938cae002bcfc93", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (AUTOSAR-Metamodell / Definitionsebene).</li>\n<li><strong>Technischer Zweck & funktionale Einordnung:</strong></li>\n<li>Definiert die Top-Level-Metamodell-Struktur für die <strong>ECU-Konfigurations-Parameterdefinition</strong> (BSW-Modul-Deskriptoren).</li>\n<li>Bildet die formale Schablone (Schema / Template), anhand derer konkrete BSW-Module (z. B. Can, Com, Os, Dem) und deren Konfigurationsparameter definiert werden, bevor diese in der ECU-Konfigurations-Wertemenge (<code>EcucValueCollection</code> bzw. Modulkonfigurationen) instanziiert werden.</li>\n<li>Verankert die Konfigurationsdefinitionen in der globalen AUTOSAR-ARXML-Hierarchie als vollwertige Paket-Elemente (<code>ARElement</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Entitäten & Klassenhierarchie</p>\n<ul class=\"fig-list\">\n<li><strong><code>ARElement</code></strong> (Eigenschaft <code>PackageableElement</code>):</li>\n<li>Repräsentiert ein eigenständiges Top-Level-Element eines Pakets (<code>AR-PACKAGE</code>).</li>\n<li>Trägt die Kennzeichnung <code>PackageableElement</code> als verpackbares Metamodellelement.</li>\n<li><strong><code>EcuParameterDefinition</code>:</strong></li>\n<li>Spezialisierung von <code>ARElement</code>.</li>\n<li>Wurzelelement der Parameterspezifikation für eine Steuergerätekonfiguration.</li>\n<li><strong><code>ModuleDef</code></strong> (mit Mixin/Aspekt <code>ParamConfMultiplicity</code>):</li>\n<li>Spezialisierung von <code>ARElement</code>. Repräsentiert die Konfigurationsdefinition eines BSW-Moduls.</li>\n<li><strong>Attribute:</strong></li>\n<li><code>apiServicePrefix :CIdentifier [0..1]</code> (definiert das C-Präfix für API-Funktionen und -Symbole des Moduls).</li>\n<li><code>supportedConfigVariant :ConfigurationVariant [1..<em>]</code> (definiert als typisierte Aufzählung mit Kardinalität <code>1..</em></code> die vom Modul unterstützten Konfigurationsvarianten).</li>\n<li><strong><code>ContainerDef</code></strong> (mit Mixins/Aspekten <code>Identifiable</code>, <code>ParamConfMultiplicity</code>):</li>\n<li>Struktur- und Gruppierungselement für Parameter und Unter-Container, das die Eigenschaften von <code>Identifiable</code> und <code>ParamConfMultiplicity</code> inkorporiert.</li>\n<li><strong>Attribut:</strong> <code>postBuildChangeable :Boolean</code> (normatives Flag, ob die Parameterwerte dieses Containers nach dem Kompilieren/Bauen austauschbar sein dürfen).</li>\n</ul>\n<p class=\"fig-p\">#### Assoziationen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li>*<em><code>EcuParameterDefinition</code> $\\rightarrow$ <code>ModuleDef</code> (<code>+module</code>, Kardinalität <code>1..</em></code>):**</li>\n<li>Eine <code>EcuParameterDefinition</code> bündelt mindestens eine oder beliebig viele BSW-Moduldefinitionen.</li>\n<li>*<em><code>ModuleDef</code> $\\blacktriangleright$ <code>ContainerDef</code> (<code>+container</code>, Kardinalität <code>1..</em></code>):**</li>\n<li>Strenge Komposition: Ein BSW-Modul besteht aus mindestens einem Root-<code>ContainerDef</code>. Die Lebensdauer der Container ist fest an das übergeordnete <code>ModuleDef</code> gebunden.</li>\n<li><strong><code>ModuleDef</code> $\\rightarrow$ <code>ModuleDef</code> (<code>+refinedModuleDef</code>, Kardinalität <code>0..1</code>):</strong></li>\n<li>Reflexive Assoziation zur Modul-Refinierung (<em>Module Refinement</em>): Ermöglicht die Spezialisierung bzw. Erweiterung einer bestehenden Moduldefinition.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Nicht zutreffend (rein statisches Metamodell):</strong></li>\n<li>Das Diagramm enthält keine Laufzeitinteraktionen, Zustände, Sequenzen oder OS-/Task-Trigger.</li>\n<li><strong>Verarbeitungskontext im AUTOSAR-Toolchain-Ablauf:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>Bereitstellung der <code>ModuleDef</code>-Standardbeschreibungen durch den BSW-Lieferanten (BSW-Paket).</li>\n<li>Optionales Ausführen der Refinement-Assoziation (<code>refinedModuleDef</code>) durch Vendor-Tools.</li>\n<li>Einlesen der <code>EcuParameterDefinition</code> in den ECU-Konfigurator (z. B. DaVinci Configurator, EB tresos).</li>\n<li>Validierung der Modul-Multiplizitäten (<code>ParamConfMultiplicity</code>) und Bindungsvarianten (<code>implementationConfigVariant</code>) gegen die konkreten Eingabewerte (<code>EcucModuleConfigurationValues</code>).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Verbindlichkeit der Struktur:</strong> Jede AUTOSAR-konforme BSW-Moduldefinition muss als <code>ModuleDef</code> angelegt sein und zwingend mindestens einen Wurzelcontainer (<code>+container [1..*]</code>) deklarieren.</li>\n<li><strong>Paketierung:</strong> <code>EcuParameterDefinition</code> und <code>ModuleDef</code> sind als <code>ARElement</code> spezialisiert und tragen den Status <code>PackageableElement</code>, wodurch sie direkt in ARXML-Paketen verwaltet werden.</li>\n<li><strong>Post-Build-Restriktion:</strong> Das Attribut <code>postBuildChangeable</code> an <code>ContainerDef</code> schreibt bindend vor, ob Werte der in diesem Container enthaltenen Parameter zur Post-Build-Zeit geändert werden dürfen.</li>\n<li><strong>Konfigurationsvarianten:</strong> Durch das Attribut <code>supportedConfigVariant :ConfigurationVariant [1..*]</code> muss für jede Moduldefinition mindestens eine explizit typisierte Konfigurationsvariante verbindlich festgelegt sein.</li>\n<li><strong>API-Präfixierung:</strong> Das optionale Attribut <code>apiServicePrefix :CIdentifier [0..1]</code> erlaubt die formale Festlegung eines C-konformen Namensraum-Präfixes für die Codegenerierung der Modul-Schnittstellen.</li>\n</ul>"}], "trans": [{"from": "FIG-ae9ce7ab8ff64b3b", "to": "FIG-a6ede4f7b3ece0cd", "fr": "R2.1.20", "tr": "R3.0.7", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>Identifiable</code> und <code>ARObject</code>: Die separaten übergeordneten Basisklassen inklusive der Vererbungsbeziehung zu <code>ContainerDef</code> sowie der Attribute <code>category: String [0..1]</code>, <code>shortName: Identifier</code> und <code>uuid: String</code> sind nicht mehr dargestellt; stattdessen ist <code>Identifiable</code> als Aspekt/Mixin direkt an <code>ContainerDef</code> deklariert.</li>\n<li><code>ARElement</code>: Die Eigenschaft <code>NonSplitableElement</code> und das Stereotyp <code>«atpIdentifiable»</code> wurden durch das Kursiv-Schlüsselwort/Mixin <code>PackageableElement</code> ersetzt.</li>\n<li><code>ModuleDef</code>: Das Attribut <code>implementationConfigVariant: String [0..1]</code> wurde ersetzt durch <code>supportedConfigVariant: ConfigurationVariant [1..*]</code>.</li>\n</ul>"}, {"from": "FIG-a6ede4f7b3ece0cd", "to": "FIG-a938cae002bcfc93", "fr": "R3.1.5", "tr": "R3.2.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>ModuleDef</code>: Um das optionale Attribut <code>apiServicePrefix :CIdentifier [0..1]</code> erweitert.</li>\n</ul>"}]};
